package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.ResolvableSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDelegatingSerializer;
import com.fasterxml.jackson.databind.util.Converter;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.function.Function;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdDelegatingSerializer_createContextual_TriageGen0Test {

    private SerializerProvider provider;
    private BeanProperty property;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        provider = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        typeFactory = mock(TypeFactory.class);
        when(provider.getTypeFactory()).thenReturn(typeFactory);
    }

    /**
     * Test Case 1: delSer is NOT null and is NOT an instance of ContextualSerializer.
     * Expected: Returns 'this'.
     */
    @Test
    public void testCreateContextual_DelegateExistsNotContextual() throws JsonMappingException {
        JsonSerializer<?> delegate = mock(JsonSerializer.class);
        // We need to bypass the protected nature or use a subclass to set the delegate
        StdDelegatingSerializer<Object> serializer = new TestStdDelegatingSerializer(delegate, null);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertSame("Should return 'this' when delegate is already set and not contextual", serializer, result);
    }

    /**
     * Test Case 2: delSer is NOT null and IS an instance of ContextualSerializer.
     * Expected: Returns a new serializer via withDelegate with the handled secondary context.
     */
    @Test
    public void testCreateContextual_DelegateExistsAndIsContextual() throws JsonMappingException {
        ContextualSerializer contextualDelegate = mock(ContextualSerializer.class);
        JsonSerializer<?> secondaryContextualDelegate = mock(JsonSerializer.class);

        when(provider.handleSecondaryContextualization(contextualDelegate, property))
                .thenReturn(secondaryContextualDelegate);

        StdDelegatingSerializer<Object> serializer = new TestStdDelegatingSerializer(contextualDelegate, null);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame("Should not return 'this' when secondary contextualization happens", serializer, result);
        assertTrue("Result should be a new instance via withDelegate", result instanceof TestStdDelegatingSerializer);
        assertEquals(secondaryContextualDelegate, ((TestStdDelegatingSerializer<?>) result).getDelegatee());
    }

    /**
     * Test Case 3: delSer is null, delegateType is null.
     * Expected: Uses converter to get type, then finds serializer via provider.
     */
    @Test
    public void testCreateContextual_DelegateNullTypeNull() throws JsonMappingException {
        JavaType targetType = mock(JavaType.class);
        JsonSerializer<?> foundSerializer = mock(JsonSerializer.class);

        // Mock converter
        Function<TypeFactory, JavaType> converterFunc = (tf) -> targetType;

        when(typeFactory.getOutputType(any())).thenReturn(targetType); // Simplified for mock
        // In actual code: delegateType = _converter.getOutputType(provider.getTypeFactory());
        // Since _converter is protected, we use our Test subclass

        StdDelegatingSerializer<Object> serializer = new TestStdDelegatingSerializer(null, null) {
            @Override
            protected Converter<Object, ?> getConverter() {
                return new Converter<Object, Object>() {
                    @Override public Class<Object> getInputType() { return Object.class; }
                    @Override public Class<Object> getOutputType() { return Object.class; }
                    @Override public Object convert(Object value) { return value; }
                    @Override public JavaType getOutputType(TypeFactory tf) { return targetType; }
                };
            }
        };

        when(provider.findValueSerializer(targetType)).thenReturn(foundSerializer);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        assertEquals(foundSerializer, ((TestStdDelegatingSerializer<?>) result).getDelegatee());
    }

    /**
     * Test Case 4: delSer is null, delegateType is NOT null.
     * Expected: Finds serializer via provider using existing delegateType.
     */
    @Test
    public void testCreateContextual_DelegateNullTypeNotNull() throws JsonMappingException {
        JavaType existingType = mock(JavaType.class);
        JsonSerializer<?> foundSerializer = mock(JsonSerializer.class);

        StdDelegatingSerializer<Object> serializer = new TestStdDelegatingSerializer(null, existingType) {
            @Override
            protected Converter<Object, ?> getConverter() {
                return mock(Converter.class); // Won't be called because delegateType != null
            }
        };

        when(provider.findValueSerializer(existingType)).thenReturn(foundSerializer);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        assertEquals(foundSerializer, ((TestStdDelegatingSerializer<?>) result).getDelegatee());
    }

    /**
     * Helper subclass to access protected fields and methods for testing.
     */
    private static class TestStdDelegatingSerializer<T> extends StdDelegatingSerializer<T> {
        private final JsonSerializer<?> manualDelegate;
        private final JavaType manualType;

        public TestStdDelegatingSerializer(JsonSerializer<?> delegate, JavaType type) {
            super(delegate);
            this.manualDelegate = delegate;
            this.manualType = type;
            // We use reflection or a trick to set fields because they are private in the real class
            // But since we are testing the logic, we simulate the state by overriding if necessary
            // or using a subclass that mimics the state.
            try {
                java.lang.reflect.Field delField = StdDelegatingSerializer.class.getDeclaredField("_delegateSerializer");
                delField.setAccessible(true);
                delField.set(this, delegate);

                java.lang.reflect.Field typeField = StdDelegatingSerializer.class.getDeclaredField("_delegateType");
                typeField.setAccessible(true);
                typeField.set(this, type);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        protected JsonSerializer<?> withDelegate(Converter<Object, ?> converter, JavaType delegateType, JsonSerializer<?> delegateSerializer) {
            return new TestStdDelegatingSerializer<>(delegateSerializer, delegateType);
        }
    }

    // Mocking the Converter interface as it's used in the code
    interface Converter<I, O> {
        O convert(I value);
        JavaType getOutputType(TypeFactory tf);
    }
}
